/* ===== Reset & Base ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: #1a1a2e;
  color: #f0e6d3;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
}

/* ===== Canvas Container ===== */
#canvas-container {
  position: absolute;
  inset: 0;
}

#canvas-container canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* ===== Timeline Container ===== */
#timeline-container {
  position: absolute;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 14px 28px;
  background: rgba(15, 15, 30, 0.85);
  border-radius: 16px;
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

#timeline-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: rgba(240, 230, 211, 0.6);
}

#timeline-track {
  position: relative;
  width: 320px;
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  cursor: pointer;
}

#timeline-progress {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #e8a87c, #d4a574);
  border-radius: 3px;
  transition: width 0.4s ease;
}

#timeline-handle {
  position: absolute;
  top: 50%;
  left: 0%;
  width: 20px;
  height: 20px;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 40% 40%, #f5d5b8, #c4956a);
  border-radius: 50%;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4), 0 0 12px rgba(232, 168, 124, 0.5);
  cursor: grab;
  transition: left 0.4s ease, transform 0.15s ease;
}

#timeline-handle:active {
  cursor: grabbing;
  transform: translate(-50%, -50%) scale(1.15);
}

.year-label {
  position: absolute;
  top: 14px;
  font-size: 11px;
  font-weight: 600;
  color: rgba(240, 230, 211, 0.4);
  transform: translateX(-50%);
  transition: color 0.3s ease, transform 0.3s ease;
  pointer-events: none;
}

.year-label.active {
  color: #f5d5b8;
  transform: translateX(-50%) scale(1.2);
}

.year-label[data-year="1965"] { left: 0%; }
.year-label[data-year="2005"] { left: 33.33%; }
.year-label[data-year="2025"] { left: 66.66%; }
.year-label[data-year="2055"] { left: 100%; }

#current-year-display {
  font-size: 28px;
  font-weight: 700;
  background: linear-gradient(135deg, #f5d5b8, #e8a87c);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  transition: all 0.4s ease;
}

/* ===== Audio Controls ===== */
#audio-controls {
  position: absolute;
  bottom: 24px;
  right: 24px;
  z-index: 100;
}

#audio-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  background: rgba(15, 15, 30, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 24px;
  color: #f0e6d3;
  font-size: 13px;
  cursor: pointer;
  backdrop-filter: blur(12px);
  transition: all 0.3s ease;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

#audio-toggle:hover {
  background: rgba(30, 30, 50, 0.9);
  border-color: rgba(232, 168, 124, 0.4);
  transform: translateY(-1px);
}

#audio-toggle .icon {
  font-size: 16px;
}

#audio-toggle.playing .icon {
  animation: pulse 1.5s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.2); }
}

/* ===== Info Panel ===== */
#info-panel {
  position: absolute;
  bottom: 24px;
  left: 24px;
  z-index: 100;
  max-width: 300px;
  padding: 16px 20px;
  background: rgba(15, 15, 30, 0.85);
  border-radius: 12px;
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  transition: all 0.4s ease;
}

#era-title {
  font-size: 16px;
  font-weight: 700;
  color: #f5d5b8;
  margin-bottom: 6px;
}

#era-description {
  font-size: 12px;
  line-height: 1.6;
  color: rgba(240, 230, 211, 0.7);
}

/* ===== Loading Screen ===== */
#loading-screen {
  position: absolute;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at center, #1a1a2e 0%, #0f0f1a 100%);
  transition: opacity 0.8s ease, visibility 0.8s ease;
}

#loading-screen.hidden {
  opacity: 0;
  visibility: hidden;
}

.loader {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.spinner {
  width: 48px;
  height: 48px;
  border: 3px solid rgba(255, 255, 255, 0.1);
  border-top-color: #e8a87c;
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.loader p {
  font-size: 14px;
  color: rgba(240, 230, 211, 0.6);
  letter-spacing: 1px;
}

/* ===== Responsive ===== */
@media (max-width: 600px) {
  #timeline-container {
    padding: 10px 16px;
    gap: 6px;
  }

  #timeline-track {
    width: 220px;
  }

  #current-year-display {
    font-size: 22px;
  }

  #info-panel {
    max-width: 240px;
    padding: 12px 16px;
  }

  #era-title { font-size: 14px; }
  #era-description { font-size: 11px; }
}

