    const nextTime = startTime + barLength;
    const timeoutId = setTimeout(() => {
      playBeatSequence(audioContext.currentTime);
    }, (nextTime - now) * 1000);
    audioNodes.push({ node: { stop: () => clearTimeout(timeoutId) }, type: 'timeout' });
  }

